<template><div class="analytics"><div class="heading"><div><h2>巡检分析</h2><p>观察任务完成、点位覆盖、异常发现和人员执行情况</p></div><el-button @click="refresh">刷新数据</el-button></div><el-row :gutter="16"><el-col :xs="24" :lg="13"><div class="chart-card"><h3>巡检任务状态</h3><div id="inspection-status" class="chart"></div></div></el-col><el-col :xs="24" :lg="11"><div class="chart-card"><h3>点位覆盖率</h3><div id="inspection-coverage" class="chart"></div></div></el-col><el-col :xs="24" :lg="14"><div class="chart-card"><h3>各点位任务与异常</h3><div id="inspection-points" class="chart"></div></div></el-col><el-col :xs="24" :lg="10"><div class="chart-card"><h3>人员完成率</h3><div id="inspection-people" class="chart"></div></div></el-col></el-row></div></template>
<script setup>
import { onMounted } from 'vue'; import * as echarts from 'echarts'; const charts=[]; const init=(id,opt)=>{const c=echarts.init(document.getElementById(id));c.setOption(opt);charts.push(c)}; const refresh=()=>charts.forEach(c=>c.resize())
onMounted(()=>{init('inspection-status',{tooltip:{trigger:'item'},legend:{bottom:4},color:['#0f9f78','#2563eb','#f59e0b','#ef4444'],series:[{type:'pie',radius:['46%','72%'],label:{formatter:'{b}\n{c} 项'},data:[{name:'已完成',value:16},{name:'执行中',value:4},{name:'待处理',value:3},{name:'漏检',value:5}]}]});init('inspection-coverage',{series:[{type:'gauge',startAngle:210,endAngle:-30,min:0,max:100,progress:{show:true,width:16,itemStyle:{color:'#0f9f78'}},axisLine:{lineStyle:{width:16,color:[[1,'#e8f3ef']]}},pointer:{itemStyle:{color:'#0f9f78'}},detail:{valueAnimation:true,formatter:'{value}%',fontSize:28,color:'#172033'},data:[{value:92}] } ]});init('inspection-points',{tooltip:{trigger:'axis'},legend:{bottom:0},grid:{left:70,right:18,top:20,bottom:35},xAxis:{type:'category',data:['配电房','消防','水泵房','空调']},yAxis:{type:'value'},series:[{name:'任务数',type:'bar',data:[12,9,7,6],itemStyle:{color:'#4f6ef7'},barGap:'15%'},{name:'异常数',type:'bar',data:[1,3,1,0],itemStyle:{color:'#f59e0b'}}]});init('inspection-people',{tooltip:{trigger:'axis'},grid:{left:55,right:18,top:20,bottom:30},xAxis:{type:'category',data:['李强','王磊','赵明','周敏']},yAxis:{type:'value',max:100,axisLabel:{formatter:'{value}%'}},series:[{type:'bar',data:[96,88,78,72],barWidth:22,itemStyle:{color:'#0f9f78',borderRadius:[6,6,0,0]},label:{show:true,position:'top',formatter:'{c}%'}}]})})
</script>
<style scoped>.analytics{padding:4px}.heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.heading h2{margin:0;color:#172033;font-size:22px}.heading p{margin:6px 0;color:#8491a5;font-size:13px}.chart-card{height:330px;margin-bottom:16px;padding:20px;background:#fff;border:1px solid #e7edf5;border-radius:12px;box-shadow:0 5px 18px rgba(31,55,90,.05)}h3{margin:0;color:#26364d;font-size:15px}.chart{height:285px}</style>
